class Solution {
    private int maxSum = Integer.MIN_VALUE;
    public int maxPathSum(TreeNode root) {
        dfs(root);
        return maxSum;
    }
    private int dfs(TreeNode node) {
        if (node == null) return 0;
        int left = Math.max(0, dfs(node.left));
        int right = Math.max(0, dfs(node.right));
        maxSum = Math.max(maxSum, left + right + node.val);
        return Math.max(left, right) + node.val;
    }
}

import java.util.*;

class Solution {
    public int maxPathSum(TreeNode root) {
        int[] maxSum = {Integer.MIN_VALUE};
        Map<TreeNode, Integer> gains = new HashMap<>();
        gains.put(null, 0);
        Deque<TreeNode> stack = new ArrayDeque<>();
        TreeNode curr = root;
        TreeNode lastVisited = null;
        while (curr != null || !stack.isEmpty()) {
            while (curr != null) {
                stack.push(curr);
                curr = curr.left;
            }
            TreeNode peek = stack.peek();
            if (peek.right != null && peek.right != lastVisited) {
                curr = peek.right;
            } else {
                stack.pop();
                int leftGain = Math.max(0, gains.getOrDefault(peek.left, 0));
                int rightGain = Math.max(0, gains.getOrDefault(peek.right, 0));
                int pathSum = leftGain + rightGain + peek.val;
                maxSum[0] = Math.max(maxSum[0], pathSum);
                gains.put(peek, Math.max(leftGain, rightGain) + peek.val);
                lastVisited = peek;
            }
        }
        return maxSum[0];
    }
}
